<?php require_once __DIR__.'/../includes/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: opportunities.php');exit;}csrf_check();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$allowed=['Pending','Shortlisted','Interview','Offer','Rejected'];if($id>0&&in_array($status,$allowed,true)){$q=$pdo->prepare('UPDATE applications SET status=? WHERE id=?');$q->execute([$status,$id]);flash('Application status updated.');}else flash('Invalid status update.','error');header('Location: opportunities.php');exit;
